#!/usr/bin/env bash
#
# Prints the GitHub release notes for a version in the layout of the previous releases: the artifact coordinates
# followed by the version's section of the changelog generated by "./gradlew changelog" (build/changelog/CHANGELOG.md).
#
# Usage: release-notes.sh <version>

set -euo pipefail

version="${1:?usage: release-notes.sh <version>}"
changelog="$(dirname "$0")/../../build/changelog/CHANGELOG.md"

# the version's section: its "## <version> (<date>)" heading and the lines up to the next "## " heading
section="$(awk -v heading="## ${version} " '
    index($0, heading) == 1 { found = 1; print; next }
    found && /^## / { exit }
    found { print }
' "${changelog}")"

if [[ -z "${section//[[:space:]]/}" ]]; then
    echo "No section for ${version} found in ${changelog}" >&2
    exit 1
fi

cat <<NOTES
## Artifacts

Maven Central: [neonbee-core-${version}](https://mvnrepository.com/artifact/io.neonbee/neonbee-core/${version})

### Maven

\`\`\`xml
<!-- https://mvnrepository.com/artifact/io.neonbee/neonbee-core -->
<dependency>
  <groupId>io.neonbee</groupId>
  <artifactId>neonbee-core</artifactId>
  <version>${version}</version>
</dependency>
\`\`\`

### Gradle

\`\`\`groovy
// https://mvnrepository.com/artifact/io.neonbee/neonbee-core
implementation group: 'io.neonbee', name: 'neonbee-core', version: '${version}'
\`\`\`

${section}
NOTES
